def input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:
    # Count repeats strictly before each position in the available prefix.
    earlier_matches = torch.tril(
        seq.unsqueeze(2).eq(seq.unsqueeze(1)), diagonal=-1
    )
    counts = earlier_matches.sum(dim=-1).float()
    repeat_feature = torch.log1p(counts).clamp(max=math.log(4.0)) / math.log(4.0)
    scale = 1.0 + 0.1 * repeat_feature * seq.ne(0).float()
    return self.dropout(self.item_emb(seq) * scale.unsqueeze(-1))

def encode(self, seq: torch.Tensor) -> torch.Tensor:
    emb = self.input_embeddings(seq)
